#region Usings
using System.Collections.Generic;
#endregion

namespace SF.CodeGeneration;

//the first and the last lines of a file, at the left margin
public static partial class CSharpFile
{
    /// <summary>
    /// <c>// &lt;auto-generated/&gt;</c>: tools (analyzers, code coverage, nullable warnings) treat the file as
    /// generated. Write it first.
    /// </summary>
    public static void AutoGeneratedHeader()
    {
        _b.AppendLine("// <auto-generated/>");
    }

    /// <summary>
    /// The lines in a banner comment at the end of the file; nothing when there are none.
    /// </summary>
    public static void Footer(IReadOnlyList<string> lines = null)
    {
        if(lines == null || lines.Count == 0)
            return;

        _b.AppendLine("/************************************************");
        for(var i = 0; i < lines.Count; i++)
            _b.AppendLine(lines[i]);

        _b.AppendLine("************************************************/");
    }
}
